# Check for potential bugs with odd n values
import sys
sys.path.insert(0, '.')
from more_itertools.recipes import sieve

# Check sieve for various n values
for n in range(1, 50):
    result = list(sieve(n))
    # Verify all results are prime
    for p in result:
        if p < 2:
            print(f"ERROR: sieve({n}) contains {p} which is not prime")
        for d in range(2, int(p**0.5) + 1):
            if p % d == 0:
                print(f"ERROR: sieve({n}) contains {p} which is divisible by {d}")
    # Verify no primes are missing
    expected_primes = [p for p in range(2, n) if all(p % d != 0 for d in range(2, int(p**0.5) + 1))]
    if result != expected_primes:
        print(f"MISMATCH: sieve({n}) = {result}, expected {expected_primes}")

print("Done checking sieve correctness")
